diff --git a/mailnews/compose/src/nsMsgCompose.cpp b/mailnews/compose/src/nsMsgCompose.cpp
index bf601d1654e..117223c6a7d 100644
--- a/mailnews/compose/src/nsMsgCompose.cpp
+++ b/mailnews/compose/src/nsMsgCompose.cpp
@@ -1922,7 +1922,12 @@ nsresult nsMsgCompose::CreateMessage(const nsACString& originalMsgURI,
       }
     }
     isFirstPass = false;
-    uri = nextUri + 1;
+    if (nextUri) {
+      // `nextUri` can be a null pointer if `strstr` did not find `://` in the
+      // URI earlier. Only increment it if that is not the case, to avoid
+      // undefined behaviors.
+      uri = nextUri + 1;
+    }
   } while (nextUri);
   PR_Free(uriList);
   return rv;
